def solve7(g, mingap):
    R,C=len(g),len(g[0])
    out=[row[:] for row in g]
    for r in range(R):
        ps=[c for c in range(C) if g[r][c]==7]
        for a,b in zip(ps,ps[1:]):
            if b-a-1>=mingap:
                for c in range(a+1,b): out[r][c]=3
    for c in range(C):
        ps=[r for r in range(R) if g[r][c]==7]
        for a,b in zip(ps,ps[1:]):
            if b-a-1>=mingap:
                for r in range(a+1,b): out[r][c]=3
    return out
